package com.sigtm.backend.controller;
import com.sigtm.backend.model.*; import com.sigtm.backend.service.AprobacionCompraService; import jakarta.validation.Valid; import lombok.RequiredArgsConstructor; import org.springframework.http.ResponseEntity; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/compras/aprobaciones") @RequiredArgsConstructor public class AprobacionCompraController {private final AprobacionCompraService service; @GetMapping("/niveles") @PreAuthorize("hasAuthority('COMPRAS:VER')") public ResponseEntity<List<NivelAprobacionCompra>> niveles(){return ResponseEntity.ok(service.niveles());} @PostMapping("/niveles") @PreAuthorize("hasAuthority('COMPRAS:APROBAR')") public ResponseEntity<NivelAprobacionCompra> nivel(@Valid @RequestBody NivelAprobacionCompra n){return ResponseEntity.ok(service.guardarNivel(n));} @PostMapping("/orden/{orderId}/nivel/{levelId}") @PreAuthorize("hasAuthority('COMPRAS:APROBAR')") public ResponseEntity<AprobacionOrdenCompra> decidir(@PathVariable Long orderId,@PathVariable Long levelId,@RequestParam String decision,@RequestParam(required=false) String comment){return ResponseEntity.ok(service.decidir(orderId,levelId,decision.toUpperCase(),comment));} @GetMapping("/orden/{orderId}") @PreAuthorize("hasAuthority('COMPRAS:VER')") public ResponseEntity<List<AprobacionOrdenCompra>> historial(@PathVariable Long orderId){return ResponseEntity.ok(service.historial(orderId));}}
